using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
namespace Videira {public partial class VideiraSite {
 void LoginPage(){var root=PageRoot("Bem-vindo à Videira");var card=Card("Acesse o painel do site",400);root.Controls.Add(card);card.Controls.Add(new Label{Text="E-mail do administrador",AutoSize=true,Location=new Point(20,60)});var email=new TextBox{Text=SiteApi.AdminEmail,ReadOnly=true,Location=new Point(20,87),Width=380};card.Controls.Add(email);card.Controls.Add(new Label{Text="Senha",AutoSize=true,Location=new Point(20,128)});var pass=new TextBox{UseSystemPasswordChar=true,Location=new Point(20,155),Width=380};card.Controls.Add(pass);var show=new CheckBox{Text="Mostrar senha",AutoSize=true,Location=new Point(20,194)};show.CheckedChanged+=(s,e)=>pass.UseSystemPasswordChar=!show.Checked;card.Controls.Add(show);var button=ActionButton("Entrar",async()=>{await api.Login(SiteApi.AdminEmail,pass.Text);pass.Clear();await Reload();account.Text="Conectado • "+SiteApi.AdminEmail;ShowPage("Painel");Notify("Conectado. Catálogo carregado do site.");},true);button.Location=new Point(20,240);card.Controls.Add(button);var recover=ActionButton("Recuperar acesso",()=>{RecoveryDialog();return Task.FromResult(0);});recover.Location=new Point(135,240);card.Controls.Add(recover);pass.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;button.PerformClick();}};card.Controls.Add(new Label{Text="Use sua conta e senha do catálogo.\nEste painel administra a loja online e funciona separado do Gestão.",Location=new Point(20,305),Size=new Size(580,60),ForeColor=Color.DimGray});dirty=false;}
 void CategoriesPage(){var root=PageRoot("Categorias de produtos");var card=Card("Criar ou renomear categoria",210);root.Controls.Add(card);var name=Input(card,"Nome da categoria",20,55,380);string selected="";var controls=Buttons();controls.Location=new Point(20,120);controls.Width=card.Width-40;controls.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top;controls.Controls.Add(ActionButton("Criar categoria",async()=>{string value=name.Text.Trim();if(value==""||value.Length>100)throw new Exception("Informe um nome de até 100 caracteres.");if(categories.Any(c=>String.Equals(c,value,StringComparison.OrdinalIgnoreCase)))throw new Exception("Esta categoria já existe.");await api.Request("/rest/v1/product_categories","POST",new{name=value});dirty=false;await Reload();CategoriesPage();Notify("Categoria criada no site.");},true));controls.Controls.Add(ActionButton("Renomear selecionada",async()=>{if(selected==""||name.Text.Trim()=="")throw new Exception("Selecione uma categoria e informe o novo nome.");await api.Request("/rest/v1/rpc/rename_product_category","POST",new{old_name=selected,new_name=name.Text.Trim()});dirty=false;await Reload();CategoriesPage();Notify("Categoria e produtos vinculados atualizados no site.");}));controls.Controls.Add(ActionButton("Limpar",()=>{selected="";name.Clear();dirty=false;return Task.FromResult(0);}));card.Controls.Add(controls);var grid=Grid();grid.Height=330;grid.MultiSelect=false;grid.DataSource=categories.Select(c=>new CategoryRow{Nome=c,Produtos=products.Count(p=>SiteApi.Read(p,"category")==c)}).ToList();grid.CellClick+=(s,e)=>{if(e.RowIndex<0)return;selected=((CategoryRow)grid.Rows[e.RowIndex].DataBoundItem).Nome;name.Text=selected;dirty=false;};root.Controls.Add(grid);root.Controls.Add(new Label{Text="Clique em uma categoria para renomear. Os produtos vinculados serão atualizados juntos.",AutoSize=true,ForeColor=Color.DimGray,Margin=new Padding(0,12,0,0)});dirty=false;}
 void MediaPage(){var root=PageRoot("Biblioteca de mídia");var tools=Buttons();var filter=new TextBox{Width=280,AccessibleName="Pesquisar imagens",Margin=new Padding(0,4,12,8)};tools.Controls.Add(filter);tools.Controls.Add(ActionButton("Atualizar",async()=>{await Reload();MediaPage();Notify("Biblioteca atualizada.");}));root.Controls.Add(tools);var count=new Label{AutoSize=true,Margin=new Padding(0,0,0,12)};root.Controls.Add(count);var grid=Grid();grid.Height=410;grid.MultiSelect=false;root.Controls.Add(grid);Action render=()=>{var rows=products.Where(p=>SiteApi.Read(p,"image_url")!=""&&SiteApi.Read(p,"name").IndexOf(filter.Text,StringComparison.CurrentCultureIgnoreCase)>=0).Select(p=>new ImageRow{Id=SiteApi.Read(p,"id"),Produto=SiteApi.Read(p,"name"),Imagem=SiteApi.Read(p,"image_url")}).ToList();grid.DataSource=rows;if(grid.Columns.Contains("Id")){grid.Columns["Id"].Visible=false;grid.Columns["Produto"].FillWeight=160;}count.Text=rows.Count+" imagens associadas a produtos • "+products.Count(p=>SiteApi.Read(p,"image_url")=="")+" produtos sem foto";};render();filter.TextChanged+=(s,e)=>render();grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0){var row=(ImageRow)grid.Rows[e.RowIndex].DataBoundItem;Editor(products.First(p=>SiteApi.Read(p,"id")==row.Id));}};root.Controls.Add(new Label{Text="Dê dois cliques para editar o produto e substituir sua imagem. Envie JPG, PNG ou WebP pelo editor.",AutoSize=true,ForeColor=Color.DimGray,Margin=new Padding(0,12,0,0)});dirty=false;}
 void SettingsPage(){var root=PageRoot("Configurações");var card=Card("Contato da loja",235);root.Controls.Add(card);var phone=Input(card,"WhatsApp com código do país e DDD",20,60,380,preview?"5545999056277":"");var save=ActionButton("Salvar alterações",async()=>{string n=new string(phone.Text.Where(Char.IsDigit).ToArray());if(n.Length<12||n.Length>15)throw new Exception("Informe o WhatsApp com país e DDD, por exemplo 5545999056277.");var rows=(object[])await api.Request("/rest/v1/store_settings?id=eq.true","PATCH",new{whatsapp=n});if(rows==null||rows.Length!=1||SiteApi.Read((Dictionary<string,object>)rows[0],"whatsapp")!=n)throw new Exception("O servidor não confirmou o contato.");dirty=false;Notify("WhatsApp atualizado no site.");},true);save.Location=new Point(20,137);card.Controls.Add(save);card.Controls.Add(new Label{Text="O contato é usado para receber os pedidos enviados pela loja.",AutoSize=true,Location=new Point(20,191),ForeColor=Color.DimGray});var info=Card("Site e acesso",190);root.Controls.Add(info);info.Controls.Add(new Label{Text="Loja: videira-loja.vercel.app\nAdministrador: "+SiteApi.AdminEmail+"\nVersão: Videira Site 2.0\nAlterações são gravadas no catálogo online após salvar.",Location=new Point(20,58),Size=new Size(580,110)});dirty=false;if(api.Connected)BeginInvoke(new Action(async()=>await Run(async()=>{var rows=(object[])await api.Request("/rest/v1/store_settings?select=whatsapp");if(!phone.IsDisposed&&rows.Length>0){phone.Text=SiteApi.Read((Dictionary<string,object>)rows[0],"whatsapp");dirty=false;}})));}
 void CheckScreens(){string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"screens-v2");Directory.CreateDirectory(folder);categories=new List<string>{"Tintos","Brancos","Espumantes"};products=Enumerable.Range(1,8).Select(i=>new Dictionary<string,object>{{"id",Guid.NewGuid().ToString()},{"name",i==1?"Vinho Tinto Reserva — exemplo de nome longo para conferir o layout":"Vinho de exemplo "+i},{"category",categories[i%3]},{"price",i%3==0?(object)null:(object)(89.9m+i)},{"country","Brasil"},{"grape","Merlot"},{"winery","Produtor de exemplo"},{"description","Dados fictícios usados somente para testar o layout."},{"image_url",i%2==0?"":"https://example.com/foto.jpg"},{"active",i%2==0},{"featured",i%3==0}}).ToList();foreach(int width in new[]{1024,1366}){Size=new Size(width,850);foreach(string view in new[]{"Painel","Produtos","Adicionar produto","Categorias","Mídia","Configurações","Entrar"}){dirty=false;if(view=="Entrar")LoginPage();else ShowPage(view);PerformLayout();FitPage();Application.DoEvents();SavePreview(Path.Combine(folder,width+"-"+view.Replace(" ","-")+".png"));if(currentRoot.Width>body.ClientSize.Width-body.Padding.Horizontal)throw new Exception("Conteúdo ultrapassa largura: "+view);CheckBounds(currentRoot,view);if(view=="Produtos"){var grid=currentRoot.Controls.OfType<DataGridView>().Single();if(grid.Rows.Count!=8)throw new Exception("Lista incompleta.");var filters=Walk(currentRoot).OfType<ComboBox>().ToArray();filters[0].SelectedIndex=2;if(grid.Rows.Count!=4)throw new Exception("Filtro de rascunhos falhou.");}}}products.Clear();ProductsPage();Application.DoEvents();var empty=currentRoot.Controls.OfType<DataGridView>().Single();if(empty.Rows.Count!=0)throw new Exception("Lista vazia inválida.");dirty=false;Dashboard();}
 void CheckBounds(Control parent,string view){foreach(Control c in parent.Controls){if(c.Visible&&!(parent is FlowLayoutPanel)&&!(c is Label)&&c.Right>parent.ClientSize.Width+2)throw new Exception("Controle cortado em "+view+": "+c.GetType().Name);CheckBounds(c,view);}}
}
public class ImageRow{public string Id{get;set;}public string Produto{get;set;}public string Imagem{get;set;}}
